/bin/zsh -lc "python3 -B - <<'PY'
from retry import retry

for budget in (1, 2, 3, 5):
    calls = []
    def succeed_last():
        calls.append(1)
        if len(calls) < budget:
            raise ConnectionError('transient')
        return 'ok'
    assert retry(succeed_last, budget) == 'ok'
    assert len(calls) == budget

    calls = []
    final_error = ConnectionError('offline')
    def fail():
        calls.append(1)
        raise final_error
    try:
        retry(fail, budget)
    except ConnectionError as caught:
        assert caught is final_error
    else:
        raise AssertionError('Final error was not raised')
    assert len(calls) == budget

for budget in (0, -1):
    calls = []
    try:
        retry(lambda: calls.append(1), budget)
    except ValueError:
        pass
    else:
        raise AssertionError('Invalid budget was accepted')
    assert calls == []

for error in (RuntimeError('permanent'), ValueError('invalid'), KeyboardInterrupt()):
    calls = []
    def fail_other():
        calls.append(1)
        raise error
    try:
        retry(fail_other, 3)
    except BaseException as caught:
        assert caught is error
    else:
        raise AssertionError('Other error was not raised')
    assert len(calls) == 1

assert retry(lambda: None, 1) is None
print('Contract edge checks passed: budgets 1, 2, 3, 5; final error identity; invalid budgets; other errors; None success.')
PY"

